2	
3	// ** For main process only. Do not import this file into the renderer **
4	// Classifies a hostname or IP literal as private/loopback. Used as an SSRF guard when deciding
5	// whether a remote URL is safe to fetch. This is a synchronous check on the literal value only;
6	// callers that must also defend against DNS rebinding resolve the host and re-check the resulting
7	// addresses with this same function (see common/bundle-spectral-ruleset.ts).
8	// Note: duplicated in the Spectral lint worker (main/lint-process.mjs), which is a plain .mjs
9	// module and cannot import this file. If this logic changes, mirror it there.
10	export function isPrivateOrLoopbackHost(hostname: string): boolean {
11	  if (hostname === 'localhost' || hostname.endsWith('.localhost')) return true;
12	  const host = hostname.startsWith('[') && hostname.endsWith(']') ? hostname.slice(1, -1) : hostname;
13	
14	  if (isIPv4(host)) {
15	    const [a, b] = host.split('.').map(Number);
16	    return (
17	      a === 127 || // 127.0.0.0/8  loopback
18	      a === 10 || // 10.0.0.0/8   private
19	      (a === 172 && b >= 16 && b <= 31) || // 172.16.0.0/12 private
20	      (a === 192 && b === 168) || // 192.168.0.0/16 private
21	      (a === 169 && b === 254)
22	    ); // 169.254.0.0/16 link-local
23	  }
24	
25	  if (isIPv6(host)) {
26	    // Expand :: notation to 8 groups so we can bit-mask the first group
27	    const halves = host.split('::');
28	    const left = halves[0] ? halves[0].split(':') : [];
29	    const right = halves.length === 2 && halves[1] ? halves[1].split(':') : [];
30	    const groups = [...left, ...Array.from<string>({ length: 8 - left.length - right.length }).fill('0'), ...right];
31	    const first = Number.parseInt(groups[0] || '0', 16);
32	    return (
33	      (groups.slice(0, 7).every(g => Number.parseInt(g, 16) === 0) && Number.parseInt(groups[7], 16) === 1) || // ::1 loopback
34	      (first & 0xfe_00) === 0xfc_00 || // fc00::/7 ULA
35	      (first & 0xff_c0) === 0xfe_80
36	    ); // fe80::/10 link-local
37	  }
38	
39	  return false;
40	}
