68	// Resolves an "extends" entry into a URL. When `base` is provided, relative paths are
69	// resolved against it — used when processing extends entries inside a remote ruleset.
70	function parseRemoteExtendsUrl(entry: string, base?: URL): URL {
71	  try {
72	    return new URL(entry, base);
73	  } catch {
74	    throw new Error(`"extends" entry "${entry}" is not a valid spectral identifier, local path, or URL.`);
75	  }
76	}
