78	// Rejects URLs that could be used for SSRF attacks:
79	// - Must be https (no http, ftp, file, etc.)
80	// - Hostname must not be a known private/loopback address
81	// - DNS resolution must not yield a private/loopback address
82	async function assertSafeRemoteUrl(url: URL): Promise<void> {
83	  if (url.protocol !== 'https:') {
84	    throw new Error(`Remote "extends" URL must use https: ${url.href}`);
85	  }
86	  const hostname = url.hostname.toLowerCase();
87	  if (!hostname || isPrivateOrLoopbackHost(hostname)) {
88	    throw new Error(`Remote "extends" URL targets a disallowed host: ${url.href}`);
89	  }
90	  // The literal hostname can still resolve to an internal address (e.g. *.localtest.me → 127.0.0.1).
91	  const records = await dns.lookup(hostname, { all: true });
92	  for (const { address } of records) {
93	    if (isPrivateOrLoopbackHost(address.toLowerCase())) {
94	      throw new Error(`Failed to resolve host. "${url.href}" resolves to a private or loopback address.`);
95	    }
96	  }
97	}
