1	import YAML from 'yaml';
2	
3	export type SpectralRulesetValidationResult = { isValid: true } | { isValid: false; error: string };
4	
5	// Top-level keys we support. We reject everything else for the time being.
6	// When adding new top-level properties, consider how they might be abused and how to mitigate.
7	const ALLOWED_TOP_LEVEL_PROPERTIES = ['rules', 'extends'];
8	
9	// These are the only built-in Spectral identities we allow in the extends property.
10	export const ALLOWED_EXTENDS_IDENTIFIERS = ['spectral:oas', 'spectral:asyncapi', 'spectral:arazzo'];
11	
12	// These are the only built-in Spectral functions we allow in ruleset "then" clauses
13	const ALLOWED_BUILTIN_FUNCTIONS = [
14	  'alphabetical',
15	  'casing',
16	  'defined',
17	  'enumeration',
18	  'falsy',
19	  'length',
20	  'pattern',
21	  'schema',
22	  'truthy',
23	  'typedEnum',
24	  'undefined',
25	  'unreferencedReusableObject',
26	  'or',
27	  'xor',
28	];
29	
30	// For security reasons we do not allow rulesets to contain certain tokens that could be used for JavaScript prototype pollution when used in certain Spectral properties (e.g. "field").
31	const PROTOTYPE_POLLUTION_TOKENS = ['__proto__', 'prototype', 'constructor'];
32	
33	export function toArray<T>(value: T | T[] | undefined): T[] {
34	  //no extends key in the ruleset
35	  if (value === undefined) {
36	    return [];
37	  }
38	  return Array.isArray(value) ? value : [value]; // handles both array and single value cases for extends in a given ruleset
39	}
40	
41	function containsPrototypePollution(value: string): boolean {
42	  return PROTOTYPE_POLLUTION_TOKENS.some(token => value.includes(token));
43	}
44	
45	// Guards a rule's "documentationUrl"
46	function isSafeUrl(value: string): boolean {
47	  try {
48	    return new URL(value).protocol === 'https:';
49	  } catch {
50	    return false;
51	  }
52	}
53	
54	function fail(error: string): SpectralRulesetValidationResult {
55	  return { isValid: false, error };
56	}
57	
58	function validateThen(ruleName: string, then: Record<string, unknown>): string | null {
59	  // We do not allow javascript prototype pollution via the "field" property as well as square brackets/dot notation that could traverse beyond a single property level.
60	  if (typeof then.field === 'string' && (containsPrototypePollution(then.field) || /[.\[\]]/.test(then.field))) {
61	    return `Rule "${ruleName}" has an invalid "field" value "${then.field}". The "field" must be a plain property name. It cannot contain ".", "[", or "]", or use reserved names like __proto__, prototype, or constructor.`;
62	  }
63	
64	  // only Spectral's documented built-in functions are reachable.
65	  if (
66	    then.function !== undefined &&
67	    (typeof then.function !== 'string' || !ALLOWED_BUILTIN_FUNCTIONS.includes(then.function))
68	  ) {
69	    return `Rule "${ruleName}" uses function "${String(then.function)}" which is not an allowed Spectral built-in function.`;
70	  }
71	
72	  return null;
73	}
74	
75	// Structural check only: each "extends" entry must be a plain string. Whether an entry is a valid
76	// identifier, local path, or remote URL — and whether a remote URL is safe to fetch (SSRF) — is
77	// decided when the ruleset is bundled (see common/bundle-spectral-ruleset.ts).
78	function validateExtends(value: unknown): string | null {
79	  for (const entry of toArray(value)) {
80	    if (Array.isArray(entry)) {
81	      return `"extends" entry ${JSON.stringify(entry)} uses tuple format (e.g. [path, severity]) which is not supported. Use a plain string instead.`;
82	    }
83	    if (typeof entry !== 'string') {
84	      return '"extends" entries must be strings.';
85	    }
86	  }
87	  return null;
88	}
89	
90	function validateRules(value: unknown): string | null {
91	  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
92	    return '"rules" must be an object.';
93	  }
94	
95	  for (const [ruleName, rule] of Object.entries(value as Record<string, unknown>)) {
96	    // allow shorthand rule definitions (boolean or severity string)
97	    if (rule === true || rule === false || typeof rule === 'string') {
98	      continue;
99	    }
100	    // protect against Javascript prototype pollution
101	    if (PROTOTYPE_POLLUTION_TOKENS.includes(ruleName)) {
102	      return `Rule name "${ruleName}" is not allowed.`;
103	    }
104	
105	    if (rule === null || typeof rule !== 'object') {
106	      return `Rule "${ruleName}" must be an object, boolean, or severity string.`;
107	    }
108	
109	    const ruleError = validateRuleBody(ruleName, rule as Record<string, unknown>);
110	    if (ruleError) {
111	      return ruleError;
112	    }
113	  }
114	  return null;
115	}
116	
117	function validateRuleBody(ruleName: string, rule: Record<string, unknown>): string | null {
118	  for (const given of toArray(rule.given)) {
119	    if (typeof given === 'string' && containsPrototypePollution(given)) {
120	      return `Rule "${ruleName}" has a "given" expression containing a disallowed token.`;
121	    }
122	  }
123	
124	  if (typeof rule.documentationUrl === 'string' && !isSafeUrl(rule.documentationUrl)) {
125	    return `Rule "${ruleName}" has a "documentationUrl" with a disallowed URL scheme.`;
126	  }
127	
128	  const thenEntries = toArray(rule.then);
129	  for (const then of thenEntries) {
130	    if (then === null || typeof then !== 'object') {
131	      continue;
132	    }
133	    const thenError = validateThen(ruleName, then as Record<string, unknown>);
134	    if (thenError) {
135	      return thenError;
136	    }
137	  }
138	  return null;
139	}
140	
141	export function validateSpectralRuleset(content: string): SpectralRulesetValidationResult {
142	  if (typeof content !== 'string' || content.trim() === '') {
143	    return fail('Ruleset file is empty.');
144	  }
145	
146	  let parsed: unknown;
147	  try {
148	    parsed = YAML.parse(content);
149	  } catch {
150	    return fail(`Ruleset is not valid YAML or JSON`);
151	  }
152	
153	  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
154	    return fail('Ruleset must be an object at the top level.');
155	  }
156	
157	  const ruleset = parsed as Record<string, unknown>;
158	  const keys = Object.keys(ruleset);
159	  if (keys.length === 0) {
160	    return fail('Ruleset must declare at least one of: rules, extends.');
161	  }
162	
163	  const disallowed = keys.filter(key => !ALLOWED_TOP_LEVEL_PROPERTIES.includes(key));
164	  if (disallowed.length > 0) {
165	    return fail(`Ruleset contains unsupported top-level keys. Only "rules" and "extends" are allowed.`);
166	  }
167	
168	  if ('extends' in ruleset) {
169	    const extendsError = validateExtends(ruleset.extends);
170	    if (extendsError) {
171	      return fail(extendsError);
172	    }
173	  }
174	
175	  if ('rules' in ruleset) {
176	    const rulesError = validateRules(ruleset.rules);
177	    if (rulesError) {
178	      return fail(rulesError);
179	    }
180	  }
181	
182	  return { isValid: true };
183	}
