import fs from 'node:fs';
import path from 'node:path';

import { app } from 'electron';

import { compileSpectralRulesetFromContent } from '~/common/bundle-spectral-ruleset';

// ** For main process only. Do not import this file into the renderer **
// Stores compiled Spectral rulesets (remote "extends" fully inlined) on disk, one per project,
// so lint runs can read a self-contained ruleset without re-fetching remote sources every time.

// Maps projectId → sha256 of the last content we compiled, so repeated writes of identical content
// skip the (potentially network-bound) recompilation and file write.
const contentHashCache = new Map<string, string>();

// Root directory for Insomnia's on-disk data. Read from INSOMNIA_DATA_PATH when set (used by tests
// and portable installs), otherwise the electron app's userData directory.
function dataPath(): string {
  return process.env.INSOMNIA_DATA_PATH || app.getPath('userData');
}

// Absolute path of the compiled ruleset for a given project.
export function compiledRulesetPathFor(projectId: string): string {
  return path.join(dataPath(), 'projects', projectId, '.spectral.yaml');
}

// Compiles the given ruleset content (inlining remote "extends") and writes it to disk for the
// project. Content-hash cached: if the same content was already compiled for this project and the
// compiled file still exists, the recompilation and write are skipped. Errors thrown by
// compileSpectralRulesetFromContent propagate to the caller.
export async function writeCompiledRuleset(projectId: string, content: string): Promise<{ compiledPath: string }> {
  const compiledPath = compiledRulesetPathFor(projectId);
  const hash = createHash('sha256').update(content).digest('hex');

  if (contentHashCache.get(projectId) === hash) {
    try {
      await fs.promises.access(compiledPath);
      // Content unchanged and the compiled file is still on disk — nothing to do.
      return { compiledPath };
    } catch {
      // The file was deleted externally (e.g. ENOENT); fall through to recompile and rewrite.
    }
  }

  const compiled = await compileSpectralRulesetFromContent(content);
  await fs.promises.mkdir(path.dirname(compiledPath), { recursive: true });
  await fs.promises.writeFile(compiledPath, compiled, { encoding: 'utf8' });
  contentHashCache.set(projectId, hash);
  return { compiledPath };
}

// Removes the project's compiled ruleset directory and clears its content-hash cache entry so the
// next writeCompiledRuleset call always recompiles.
export async function deleteCompiledRuleset(projectId: string): Promise<void> {
  await fs.promises.rm(path.dirname(compiledRulesetPathFor(projectId)), { recursive: true, force: true });
  contentHashCache.delete(projectId);
}
