  it('inlines nested remote extends, preserves spectral:oas, drops URLs', async () => {
    vi.mocked(fetch).mockImplementation(async (input: any) => {
      const href = String(input);
      if (href === 'https://example.com/a.yaml') {
        return resp(`extends:\n  - "spectral:oas"\n  - "./b.yaml"\nrules:\n  a-rule:\n    given: "$"\n    then:\n      function: truthy\n`);
